  | 0, 0, 0 => karm0_0_0_0RB1LC_1RC1RD_0LC1LA_1RB0RA
  | 0, 1, 0 => karm0_1_0_0RB1LC_1RC1RD_0LC1LA_1RB0RA
  | _, _, _ => karm0_0_0_0RB1LC_1RC1RD_0LC1LA_1RB0RA
  end.

