  | StB, S1 => mk S1 DR StB
  | StC, S0 => mk S1 DR StB
  | StC, S1 => mk S1 DL StD
  | StD, S0 => mk S1 DL StC
  | StD, S1 => mk S0 DL StA
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_0RB1RA_0LC1RB_1RB1LD_1LC0LA : list Instr := [].
Local Notation tm := (tm_wrap_trs tm_0RB1RA_0LC1RB_1RB1LD_1LC0LA pins_0RB1RA_0LC1RB_1RB1LD_1LC0LA).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_0RB1RA_0LC1RB_1RB1LD_1LC0LA : Fam := mkFam 2 [[S1;S1];[S1;S0]] [] [[S1;S0]] Binary 1 [mkFill 1 [] 0 [] 0] StB S0 true [].
Local Notation FAM := fam_0RB1RA_0LC1RB_1RB1LD_1LC0LA.

(** ** The ladder, as DATA

    3 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_0RB1RA_0LC1RB_1RB1LD_1LC0LA : list (LRule * list rstep) :=
  [(mkLRule (mkC StB (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) (mkC StB (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StD (mkS [S1;S0] [] 0 0 []) S0 (mkS [] [] 0 0 [])) (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S1] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StD (mkS [S1;S0] [] 0 0 []) S0 (mkS [] [] 0 0 [])) (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S1] [] 0 0 [])) 0 2, [RB (SWin 2)])].
Local Notation lad := lad_0RB1RA_0LC1RB_1RB1LD_1LC0LA.

Definition rules_0RB1RA_0LC1RB_1RB1LD_1LC0LA : list LRule := map fst lad.
Local Notation rules := rules_0RB1RA_0LC1RB_1RB1LD_1LC0LA.

Lemma ladder_ok_0RB1RA_0LC1RB_1RB1LD_1LC0LA : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_0RB1RA_0LC1RB_1RB1LD_1LC0LA : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_0RB1RA_0LC1RB_1RB1LD_1LC0LA. Qed.

