  | _, _ => farm1_0_1RB0RC_1LA1RA_0LD1LC_0RB1LD  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB0RC_1LA1RA_0LD1LC_0RB1LD (r ph : nat) : nat :=
